import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"韩碑","description":"","frontmatter":{"title":"韩碑","date":"2026-11-23T00:00:00.000Z","seq":11,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"李商隐","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/韩碑.md","filePath":"blogs/唐诗三百首·七言古诗/韩碑.md"}'),o={name:"blogs/唐诗三百首·七言古诗/韩碑.md"};function l(c,a,n,m,r,z){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="韩碑" tabindex="-1">韩碑 <a class="header-anchor" href="#韩碑" aria-label="Permalink to &quot;韩碑&quot;">​</a></h1><p class="poem-meta">唐 · 李商隐　·　七言古诗</p><div class="poem"><p class="poem-stanza">元和天子神武姿，彼何人哉轩与羲。</p><p class="poem-stanza">誓将上雪列圣耻，坐法宫中朝四夷。</p><p class="poem-stanza">淮西有贼五十载，封狼生䝙䝙生罴。</p><p class="poem-stanza">不据山河据平地，长戈利矛日可麾。</p><p class="poem-stanza">帝得圣相相曰度，贼斫不死神扶持。</p><p class="poem-stanza">腰悬相印作都统，阴风惨澹天王旗。</p><p class="poem-stanza">愬武古通作牙爪，仪曹外郎载笔随。</p><p class="poem-stanza">行军司马智且勇，十四万众犹虎貔。</p><p class="poem-stanza">入蔡缚贼献太庙，功无与让恩不訾。</p><p class="poem-stanza">帝曰汝度功第一，汝从事愈宜为辞。</p><p class="poem-stanza">愈拜稽首蹈且舞，金石刻画臣能为。</p><p class="poem-stanza">古者世称大手笔，此事不系于职司。</p><p class="poem-stanza">当仁自古有不让，言讫屡颔天子颐。</p><p class="poem-stanza">公退斋戒坐小阁，濡染大笔何淋漓。</p><p class="poem-stanza">点窜尧典舜典字，涂改清庙生民诗。</p><p class="poem-stanza">文成破体书在纸，清晨再拜铺丹墀。</p><p class="poem-stanza">表曰臣愈昧死上，咏神圣功书之碑。</p><p class="poem-stanza">碑高三丈字如斗，负以灵鳌蟠以螭。</p><p class="poem-stanza">句奇语重喻者少，谗之天子言其私。</p><p class="poem-stanza">长绳百尺拽碑倒，粗砂大石相磨治。</p><p class="poem-stanza">公之斯文若元气，先时已入人肝脾。</p><p class="poem-stanza">汤盘孔鼎有述作，今无其器存其辞。</p><p class="poem-stanza">呜呼圣王及圣相，相与烜赫流淳熙。</p><p class="poem-stanza">公之斯文不示后，曷与三五相攀追。</p><p class="poem-stanza">愿书万本诵万遍，口角流沫右手胝。</p><p class="poem-stanza">传之七十有二代，以为封禅玉检明堂基。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
